<script>
  import { toStyleString } from '@splendidlabz/utils'
  const {
    class: klass = '',
    id,
    link,
    title,
    short = false,
    start = 0,
    timestamp = 0, // alias for start
  } = $props()

  /**
   * Extracts the video ID from any YouTube URL form
   * (watch?v=, youtu.be, embed, shorts) or returns the value as-is
   * @param {string} url - YouTube URL or bare video ID
   * @returns {string|undefined} Video ID
   */
  function getVideoId(url) {
    if (!url) return undefined
    const match = url.match(/(?:v=|youtu\.be\/|embed\/|shorts\/)([\w-]{11})/)
    return match ? match[1] : url.split('/').pop()
  }

  const _id = $derived(id || getVideoId(link))
  const src = $derived(
    `https://www.youtube.com/embed/${_id}?vq=highres&start=${start || timestamp}&cc_load_policy=1&cc_lang_pref=en`,
  )
  const style = $derived(
    toStyleString({ width: '100%', aspectRatio: short ? '9/16' : '16/9' }),
  )
</script>

<div class="youtube {klass}">
  <iframe
    {style}
    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
    allowfullscreen
    frameborder="0"
    {src}
    {title}
  ></iframe>
</div>
